public class Dialogue {
    private String text;
    private List<Choice> choices;

    public Dialogue(String text, List<Choice> choices) {
        this.text = text;
        this.choices = choices;
    }

    public void display() {
        System.out.println(text);
        for (int i = 0; i < choices.size(); i++) {
            System.out.println((i + 1) + ". " + choices.get(i).getText());
        }
    }

    public Dialogue choose(int choiceIndex) {
        return choices.get(choiceIndex).getNextDialogue();
    }
}

